namespace fx{class MeterComponent:public juce::Component,private juce::Timer{public:MeterComponent(){startTimerHz(30);}void setLevel(float l,float r){tl=juce::jlimit(0.f,1.f,l);tr=juce::jlimit(0.f,1.f,r);}void paint(juce::Graphics&g)override{auto b=getLocalBounds().toFloat();float m=b.getWidth()*.42f;draw(g,b.removeFromLeft(m),sl);b.removeFromLeft(b.getWidth()*.16f);draw(g,b,sr);}private:float tl=0,tr=0,sl=0,sr=0;void timerCallback()override{sl=sl<tl?tl:sl*.85f;sr=sr<tr?tr:sr*.85f;tl*=.92f;tr*=.92f;repaint();}void draw(juce::Graphics&g,juce::Rectangle<float>r,float l){g.setColour(col::meterBg);g.fillRoundedRectangle(r,2);auto a=r.removeFromBottom(r.getHeight()*l);g.setColour(l<.6f?col::meterLow:(l<.85f?col::meterMid:col::meterHigh));g.fillRoundedRectangle(a,2);if(l>.98f){g.setColour(col::meterClip);g.fillRect(r.getX(),r.getY(),r.getWidth(),3.0f);}}};class LEDComponent:public juce::Component{public:void setOn(bool v){on=v;repaint();}void setAccent(juce::Colour c){a=c;}void paint(juce::Graphics&g)override{auto b=getLocalBounds().toFloat().reduced(1);auto c=on?a:col::ledOff;g.setColour(c);g.fillEllipse(b);if(on){g.setColour(c.withAlpha(.35f));g.fillEllipse(b.expanded(3));}}private:bool on=false;juce::Colour a{col::meterHigh};};namespace preset{inline juce::File findFxFolder(const juce::String&n){auto d=juce::File::getSpecialLocation(juce::File::currentExecutableFile).getParentDirectory();for(int i=0;i<12;++i){if(d.getChildFile("Presets").isDirectory())return d;auto x=d.getChildFile("FX").getChildFile(n);if(x.getChildFile("Presets").isDirectory())return x;auto y=d.getChildFile(n);if(y.getChildFile("Presets").isDirectory())return y;auto p=d.getParentDirectory();if(p==d)break;d=p;}return{};}inline juce::File findFactoryBank(const juce::String&n){auto d=findFxFolder(n);return d.isDirectory()?d.getChildFile("Presets").getChildFile("factory_bank.json"):juce::File{};}inline juce::File userPresetFolder(const juce::String&n){return juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory).getChildFile("Musique FX").getChildFile(n).getChildFile("Presets").getChildFile("User");}inline juce::Array<juce::var> loadPresetsFromBank(const juce::File&f){juce::Array<juce::var>o;if(!f.existsAsFile())return o;auto j=juce::JSON::parse(f.loadFileAsString());if(auto*x=j.getDynamicObject())if(auto*a=x->getProperty("presets").getArray())for(const auto&p:*a)o.add(p);return o;}inline juce::Array<juce::var> loadAllPresets(const juce::String&n){juce::Array<juce::var>o;o.addArray(loadPresetsFromBank(findFactoryBank(n)));auto u=userPresetFolder(n);if(u.isDirectory())for(auto&f:u.findChildFiles(juce::File::findFiles,false,"*.json")){auto i=juce::JSON::parse(f.loadFileAsString());if(auto*x=i.getDynamicObject()){if(x->getProperty("name").toString().isEmpty())x->setProperty("name",f.getFileNameWithoutExtension());o.add(i);}}return o;}inline bool saveUserPreset(const juce::String&n,const juce::String&p,const juce::StringArray&ids,juce::AudioProcessorValueTreeState&s){auto u=userPresetFolder(n);if(!u.createDirectory())return false;juce::DynamicObject::Ptr o=new juce::DynamicObject();o->setProperty("name",p);for(auto&id:ids)if(auto*r=s.getRawParameterValue(id))o->setProperty(id,r->load());auto q=p.retainCharacters("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-");if(q.isEmpty())q="Preset";return u.getChildFile(juce::Time::getCurrentTime().formatted("%Y%m%d_%H%M%S")+"_"+q+".json").replaceWithText(juce::JSON::toString(juce::var(o)));}inline void applyToAPVTS(juce::AudioProcessorValueTreeState&s,const juce::var&p){auto*o=p.getDynamicObject();if(!o)return;for(int i=0;i<o->getProperties().size();++i){auto k=o->getProperties().getName(i);if(k==juce::Identifier("name"))continue;if(auto*x=s.getParameter(k.toString())){float v=(float)o->getProperty(k);x->setValueNotifyingHost(x->convertTo0to1(v));}}}}namespace ui{inline void markUnsupportedControl(juce::Button&b){b.setEnabled(false);b.setTooltip("Unavailable in this build");b.setAlpha(.45f);}}namespace paint{inline void header(juce::Graphics&g,int w,juce::Colour a){g.setColour(col::surfPrimary);g.fillRect(0,0,w,dim::headerH);g.setColour(a);g.fillRect(0,dim::headerH-2,w,2);}inline void presetBar(juce::Graphics&g,int w){g.setColour(col::surfPrimary.brighter(.04f));g.fillRect(0,dim::headerH,w,dim::presetBarH);g.setColour(col::divider);g.drawHorizontalLine(dim::headerH+dim::presetBarH-1,0,(float)w);}inline void graphArea(juce::Graphics&g,int w){int t=dim::headerH+dim::presetBarH;g.setColour(col::graphBg);g.fillRect(0,t,w,dim::visualH);}inline void graphGrid(juce::Graphics&g,int w,int c=32,int r=32){int t=dim::headerH+dim::presetBarH,b=t+dim::visualH;g.setColour(col::gridMinor);for(float x=16;x<w-16;x+=(float)c)g.drawVerticalLine((int)x,(float)t+8,(float)b-8);for(float y=(float)t+8;y<b-8;y+=(float)r)g.drawHorizontalLine((int)y,16,(float)w-16);}inline void controls(juce::Graphics&g,int w,int n=6){int t=dim::headerH+dim::presetBarH+dim::visualH;juce::ColourGradient q(col::surfPrimary.brighter(.03f),0,(float)t,col::surfPrimary.darker(.02f),0,(float)(t+dim::controlsH),false);g.setGradientFill(q);g.fillRect(0,t,w,dim::controlsH);g.setColour(col::divider);g.drawHorizontalLine(t,0,(float)w);int kw=w/n,tw=n*kw,sx=(w-tw)/2;juce::Rectangle<float>p((float)sx+10,(float)t+10,(float)tw-20,(float)dim::controlsH-20);g.setColour(col::surfSecondary.withAlpha(.5f));g.fillRoundedRectangle(p,8);g.setColour(col::border.withAlpha(.5f));g.drawRoundedRectangle(p,8,1);g.setColour(col::divider.withAlpha(.3f));for(int i=1;i<n;++i){float x=(float)sx+i*kw;g.drawVerticalLine((int)x,(float)t+20,(float)(t+dim::controlsH-20));}}inline void footer(juce::Graphics&g,int w){int t=dim::appH-dim::footerH;g.setColour(col::surfPrimary.darker(.05f));g.fillRect(0,t,w,dim::footerH);g.setColour(col::divider);g.drawHorizontalLine(t,0,(float)w);}inline void footerLabel(juce::Graphics&g,const juce::String&s,int x,int w){int t=dim::appH-dim::footerH;g.setColour(col::textMuted);g.setFont(juce::Font(juce::FontOptions{}.withHeight(10).withStyle("Bold")));g.drawText(s,x,t+2,w,12,juce::Justification::centred);}inline void outline(juce::Graphics&g,juce::Rectangle<int>b){g.setColour(col::border);g.drawRect(b,1);}}}
